/* CPU model for the mechanically lifted routines (c/auto/<ver>/*.c, generated by tools/lift.py). */
#pragma once
#include <stdint.h>
#include <setjmp.h>
#include "../core.h"

typedef struct { uint8_t a, x, y, sp, c, z, n, v, d, i; } Cpu;
extern Cpu R;

/* loop budget: tests bound runaway loops; production leaves g_budget huge */
extern int g_budget; extern jmp_buf g_jmp; extern int g_abort;   /* g_abort: 1 budget, 2 brk, 3 unsupported, 4 unknown target */
#define BUDGET() do { if (--g_budget < 0) { g_abort = 1; longjmp(g_jmp, 1); } } while (0)

extern int g_trace_on; void g13_trace(uint16_t pc);
#define TR(pc) do { if (g_trace_on) g13_trace(pc); } while (0)
#define NZ(v) do { R.z = ((uint8_t)(v) == 0); R.n = ((uint8_t)(v) >> 7) & 1; } while (0)
uint8_t rd(uint16_t a);
void wr(uint16_t a, uint8_t v);
uint16_t rd16zp(uint8_t a);
uint16_t rd16bug(uint16_t a);           /* JMP (ind) with the 6502 page-wrap bug */
void adc(uint8_t m);
void sbc(uint8_t m);
void cmp8(uint8_t r, uint8_t m);
void bit8(uint8_t m);
uint8_t asl8(uint8_t v); uint8_t lsr8(uint8_t v); uint8_t rol8(uint8_t v); uint8_t ror8(uint8_t v);
void push16(uint16_t v);
void ret_check(uint16_t ret);          /* after a JSR returns: pops the return address and aborts if the callee tampered with it */
void push(uint8_t v); uint8_t pull(void);
uint8_t getp(void); void setp(uint8_t p);
void call_addr(uint16_t a);             /* generated: CPU address -> lifted routine (current PRG bank) */
void cpu_brk(void); void cpu_unsupported(const char *why); void cpu_unknown_target(uint16_t a);
extern const char *g_unsupported_why;

/* instruction macros used by the lifted code */
#define LDA(v) do { R.a = (uint8_t)(v); NZ(R.a); } while (0)
#define LDX(v) do { R.x = (uint8_t)(v); NZ(R.x); } while (0)
#define LDY(v) do { R.y = (uint8_t)(v); NZ(R.y); } while (0)
#define STA(ea) wr((ea), R.a)
#define STX(ea) wr((ea), R.x)
#define STY(ea) wr((ea), R.y)
#define AND(v) do { R.a &= (uint8_t)(v); NZ(R.a); } while (0)
#define ORA(v) do { R.a |= (uint8_t)(v); NZ(R.a); } while (0)
#define EOR(v) do { R.a ^= (uint8_t)(v); NZ(R.a); } while (0)
#define INC_M(ea) do { uint16_t e_ = (ea); uint8_t v_ = (uint8_t)(rd(e_) + 1); wr(e_, v_); NZ(v_); } while (0)
#define DEC_M(ea) do { uint16_t e_ = (ea); uint8_t v_ = (uint8_t)(rd(e_) - 1); wr(e_, v_); NZ(v_); } while (0)
#define ASL_M(ea) do { uint16_t e_ = (ea); wr(e_, asl8(rd(e_))); } while (0)
#define LSR_M(ea) do { uint16_t e_ = (ea); wr(e_, lsr8(rd(e_))); } while (0)
#define ROL_M(ea) do { uint16_t e_ = (ea); wr(e_, rol8(rd(e_))); } while (0)
#define ROR_M(ea) do { uint16_t e_ = (ea); wr(e_, ror8(rd(e_))); } while (0)
#define ASL_A() (R.a = asl8(R.a))
#define LSR_A() (R.a = lsr8(R.a))
#define ROL_A() (R.a = rol8(R.a))
#define ROR_A() (R.a = ror8(R.a))
#define PHA() push(R.a)
#define PHP() push((uint8_t)(getp() | 0x30))
#define PLA() do { R.a = pull(); NZ(R.a); } while (0)
#define PLP() setp(pull())
#define TAX() do { R.x = R.a; NZ(R.x); } while (0)
#define TAY() do { R.y = R.a; NZ(R.y); } while (0)
#define TXA() do { R.a = R.x; NZ(R.a); } while (0)
#define TYA() do { R.a = R.y; NZ(R.a); } while (0)
#define TSX() do { R.x = R.sp; NZ(R.x); } while (0)
#define TXS() (R.sp = R.x)
#define INX() do { R.x++; NZ(R.x); } while (0)
#define INY() do { R.y++; NZ(R.y); } while (0)
#define DEX() do { R.x--; NZ(R.x); } while (0)
#define DEY() do { R.y--; NZ(R.y); } while (0)
#define CLC() (R.c = 0)
#define SEC() (R.c = 1)
#define CLI() (R.i = 0)
#define SEI() (R.i = 1)
#define CLD() (R.d = 0)
#define SED() (R.d = 1)
#define CLV() (R.v = 0)
